import { useReducer } from 'react';
import { ACCIDENTS, getConsumptionStage, ACTIONS, STARTING_BUILDINGS,
    BUILDINGS, hexNeighbors, canPlaceBuilding, TECH_OPTIONS,
    MAP_RADIUS, TERRAIN_MAP, TERRAIN } from './gameData';

const INITIAL_STATE = {
    turn: 1,
    // 'input' → 'select' → 'action' → 'accident' → ['consumption'] → 'input'
    phase: 'input',

    // Survival resources (시트 기준 시작값)
    food:      4,
    oxygen:    0,   // 데포 행 없음 — 산소공장 로컬에만 존재
    sanity:    2,
    radiation: 0,

    // Depot pool
    power:       2,
    materials:   6,
    batteries:   0,
    automatron:  0,

    // Dice state
    dice: [null, null, null],  // entered values per die
    actionIdx: [],             // indices (0/1/2) of the 2 chosen AP dice
    noAccident: false,         // true for double/triple 1s

    // Current phase data
    apPool: 0,          // AP available for current slot (or combined pool)
    apUsed: 0,
    dieSlots: null,     // null | [{ap, used}]  — 주사위별 슬롯
    combineMode: false, // true = 두 주사위 합산 → 행동 1개
    accidentDice: [null, null], // 2d6 for accident check (sum 2-12)
    accidentResult: null,
    consumption: null,

    // Tech bonuses (5 checkboxes, one every 5 turns)
    techChoices: [],
    pendingTech: false,
    radiationMax: 4,   // 시트 기준 4칸, +3 Rad Max 기술 보너스로 증가

    // Construction mode
    construction: null,  // null | { step: 'select_building' | 'place', buildingType: string|null }

    // Map & buildings
    buildings: { ...STARTING_BUILDINGS },
    roverBuilt: false,

    // shuttle 필드 제거 — 송신기: 건물에서 카운트, 배터리: 보급 창고 직접 사용

    gameOver: false,
    victory:  false,
    gameOverReason: null,
};

function clamp(val, min, max) { return Math.max(min, Math.min(max, val)); }

// 행동 완료 후 슬롯 전진: split → 다음 슬롯으로, combine → 모든 슬롯 소진
function advanceSlot(state) {
    const slots = state.dieSlots;
    if (!slots) return state;
    if (state.combineMode) {
        return { ...state, dieSlots: slots.map(s => ({ ...s, used: true })) };
    } else {
        const activeIdx = slots.findIndex(s => !s.used);
        if (activeIdx < 0) return state;
        const dieSlots = slots.map((s, i) => i === activeIdx ? { ...s, used: true } : s);
        const nextSlot = dieSlots.find(s => !s.used);
        return { ...state, dieSlots, apPool: nextSlot?.ap || 0, apUsed: 0 };
    }
}

// ─── Local storage helpers ────────────────────────────────────────────────────

// Add amt to buildings of given type (up to storeCap). Returns { newState, overflow }.
function addToStore(state, buildingType, amt) {
    const def = BUILDINGS[buildingType];
    if (!def?.storeCap || amt <= 0) return { newState: state, overflow: amt };
    let rem = amt;
    const buildings = { ...state.buildings };
    for (const key of Object.keys(buildings)) {
        if (buildings[key].type !== buildingType || rem <= 0) continue;
        const space = def.storeCap - (buildings[key].store || 0);
        const add = Math.min(space, rem);
        if (add > 0) {
            buildings[key] = { ...buildings[key], store: (buildings[key].store || 0) + add };
            rem -= add;
        }
    }
    return { newState: { ...state, buildings }, overflow: rem };
}

// Drain amt from buildings storing given resType. Returns { newState, unmet }.
function drainFromStores(state, resType, amt) {
    if (amt <= 0) return { newState: state, unmet: 0 };
    let rem = amt;
    const buildings = { ...state.buildings };
    for (const key of Object.keys(buildings)) {
        if (rem <= 0) break;
        const def = BUILDINGS[buildings[key].type];
        if (def?.storeRes !== resType) continue;
        const drain = Math.min(buildings[key].store || 0, rem);
        if (drain > 0) {
            buildings[key] = { ...buildings[key], store: (buildings[key].store || 0) - drain };
            rem -= drain;
        }
    }
    return { newState: { ...state, buildings }, unmet: rem };
}

// Drain amt from buildings of a SPECIFIC type (not by resType). Returns { newState, unmet }.
function drainFromBuildingType(state, buildingType, amt) {
    if (amt <= 0) return { newState: state, unmet: 0 };
    let rem = amt;
    const buildings = { ...state.buildings };
    for (const key of Object.keys(buildings)) {
        if (rem <= 0) break;
        if (buildings[key].type !== buildingType) continue;
        const drain = Math.min(buildings[key].store || 0, rem);
        if (drain > 0) {
            buildings[key] = { ...buildings[key], store: (buildings[key].store || 0) - drain };
            rem -= drain;
        }
    }
    return { newState: { ...state, buildings }, unmet: rem };
}

// Total of resType stored across all building local stores.
function totalInStores(state, resType) {
    return Object.values(state.buildings).reduce((sum, bld) => {
        const def = BUILDINGS[bld.type];
        return def?.storeRes === resType ? sum + (bld.store || 0) : sum;
    }, 0);
}

function applyResourceDelta(state, res, delta) {
    const max = res === 'radiation' ? (state.radiationMax || 10) : 10;

    let next;
    if (delta < 0 && (res === 'food' || res === 'oxygen' || res === 'sanity')) {
        // Drain building local stores first, then survival counter
        const { newState, unmet } = drainFromStores(state, res, -delta);
        next = { ...newState, [res]: clamp((newState[res] ?? 0) - unmet, 0, max) };
    } else {
        next = { ...state, [res]: clamp((state[res] ?? 0) + delta, 0, max) };
    }

    // Sanity 1 도달 → 기술 보너스 발동 (한 번만)
    if (res === 'sanity' && next.sanity === 1 && (state.sanity ?? 0) > 1
            && !next.pendingTech && (next.techChoices || []).length < 5) {
        return checkGameOver({ ...next, pendingTech: true });
    }
    return checkGameOver(next);
}

function applyEffects(state, effects) {
    return effects.reduce((s, { res, d }) => applyResourceDelta(s, res, d), state);
}

function checkGameOver(state) {
    if (state.gameOver || state.victory) return state;
    // Food/oxygen: check global + local stores combined
    if ((state.food ?? 0) + totalInStores(state, 'food')     <= 0) return { ...state, gameOver: true, gameOverReason: 'food'     };
    if ((state.oxygen ?? 0) + totalInStores(state, 'oxygen') <= 0) return { ...state, gameOver: true, gameOverReason: 'oxygen'   };
    if (state.sanity   <= 0) return { ...state, gameOver: true, gameOverReason: 'sanity'   };
    if (state.radiation >= (state.radiationMax || 10)) return { ...state, gameOver: true, gameOverReason: 'radiation' };
    return state;
}

function checkVictory(state) {
    const transceivers = Object.values(state.buildings).filter(b => b.type === 'transceiver').length;
    const totalFood    = (state.food   ?? 0) + totalInStores(state, 'food');
    const totalOxygen  = (state.oxygen ?? 0) + totalInStores(state, 'oxygen');
    const totalBat     = (state.batteries ?? 0) + totalInStores(state, 'batteries');
    if (transceivers >= 3 && totalBat >= 6 && totalOxygen >= 5 && totalFood >= 5)
        return { ...state, victory: true };
    if (state.turn > 75) return { ...state, gameOver: true, gameOverReason: 'timeout' };
    return state;
}

function reducer(state, action) {
    if (state.gameOver || state.victory) {
        if (action.type === 'RESTART') return { ...INITIAL_STATE };
        return state;
    }

    switch (action.type) {

        case 'SET_DIE': {
            const dice = [...state.dice];
            dice[action.idx] = action.value;
            return { ...state, dice };
        }

        case 'CONFIRM_INPUT': {
            const vals = state.dice;
            if (vals.some(v => v === null)) return state;

            // Special: double 1s → 2 AP (no accident), triple 1s → 6 AP (no accident)
            const all1 = vals.every(v => v === 1);
            const two1 = vals.filter(v => v === 1).length >= 2;
            if (all1) return { ...state, phase: 'action', dieSlots: [{ ap: 6, used: false }], combineMode: true,  apPool: 6, apUsed: 0, noAccident: true };
            if (two1) return { ...state, phase: 'action', dieSlots: [{ ap: 2, used: false }], combineMode: true,  apPool: 2, apUsed: 0, noAccident: true };

            return { ...state, phase: 'select', actionIdx: [], noAccident: false };
        }

        case 'TOGGLE_DIE': {
            if (state.phase !== 'select') return state;
            const idx = action.idx;
            const cur = state.actionIdx;
            let next;
            if (cur.includes(idx)) {
                next = cur.filter(i => i !== idx);
            } else if (cur.length < 2) {
                next = [...cur, idx];
            } else {
                return state;
            }
            return { ...state, actionIdx: next };
        }

        case 'CONFIRM_SELECT': {
            if (state.actionIdx.length !== 2) return state;
            const [a, b] = state.actionIdx;
            const dieA = state.dice[a];
            const dieB = state.dice[b];
            const unchosenIdx = [0, 1, 2].find(i => !state.actionIdx.includes(i));
            const leftoverDie = state.dice[unchosenIdx];
            return {
                ...state,
                phase: 'action',
                dieSlots: [{ ap: dieA, used: false }, { ap: dieB, used: false }],
                combineMode: false,
                apPool: dieA,   // 첫 번째 주사위 AP부터 시작
                apUsed: 0,
                accidentDice: [leftoverDie, null],
            };
        }

        case 'DO_ACTION': {
            const act = ACTIONS.find(a => a.id === action.id);
            if (!act || act.apCost === 'var') return state;

            const mult = action.mult || 1;
            const cost = act.x2x3 ? mult * (act.apPerMult || 2) : act.apCost;
            const remaining = state.apPool - state.apUsed;
            if (remaining < cost) return state;

            if (act.reqBuilding) {
                const hasIt = Object.values(state.buildings).some(b => b.type === act.reqBuilding && b.active);
                if (!hasIt) return state;
            }

            let next = { ...state, apUsed: state.apUsed + cost };

            // 분리기/재활용기 설치 단계 진행 (별도 처리)
            if (act.id === 'setup_separator' || act.id === 'setup_recycler') {
                const bType = act.id === 'setup_separator' ? 'separator' : 'recycler';
                const def   = BUILDINGS[bType];
                const entry = Object.entries(next.buildings)
                    .find(([, b]) => b.type === bType && !b.active);
                if (entry) {
                    const [key, bld] = entry;
                    const newStep = (bld.setupStep || 1) + 1;
                    const done    = newStep >= def.setupSteps;
                    next = { ...next, buildings: { ...next.buildings, [key]: { ...bld, setupStep: newStep, active: done } } };
                }
                return advanceSlot(next);
            }

            if (act.out) {
                const res = act.out.res;
                const amt = act.x2x3 ? mult : act.out.amt;

                switch (act.id) {
                    case 'salvage': {
                        // 채굴: 분리기 로컬 저장소에 쌓임, 초과분은 글로벌
                        const { newState, overflow } = addToStore(next, 'separator', amt);
                        next = overflow > 0
                            ? { ...newState, materials: Math.max(0, (newState.materials || 0) + overflow) }
                            : newState;
                        break;
                    }
                    case 'recycle': {
                        // 재활용: 분리기 로컬에서 꺼내 → 재활용기 로컬에 쌓임, 초과분 글로벌
                        const { newState: s2, unmet } = drainFromStores(next, 'materials', amt);
                        const gained = amt - unmet;
                        if (gained > 0) {
                            const { newState: s3, overflow } = addToStore(s2, 'recycler', gained);
                            next = overflow > 0
                                ? { ...s3, materials: Math.max(0, (s3.materials || 0) + overflow) }
                                : s3;
                        } else {
                            next = s2;
                        }
                        break;
                    }
                    case 'produce_food': {
                        // 생산(식량): 식량 플랜트 로컬 → 초과분 글로벌 생존 카운터
                        const { newState, overflow } = addToStore(next, 'food_plant', amt);
                        next = overflow > 0 ? applyResourceDelta(newState, 'food', overflow) : newState;
                        break;
                    }
                    case 'produce_oxygen': {
                        // 생산(산소): 산소 플랜트 로컬 → 초과분 글로벌
                        const { newState, overflow } = addToStore(next, 'oxygen_plant', amt);
                        next = overflow > 0 ? applyResourceDelta(newState, 'oxygen', overflow) : newState;
                        break;
                    }
                    case 'produce_cryo': {
                        // 냉동탱크: 단독으로 식량/산소 중 하나 생산 — cryo 로컬 저장, 초과 시 양쪽 중 첫 여유 있는 쪽으로
                        const { newState: sC, overflow: ovC } = addToStore(next, 'cryo_tank', amt);
                        if (ovC > 0) {
                            // 인접 플랜트 타입으로 오버플로우 흡수
                            const cryoHexes = Object.entries(sC.buildings).filter(([,b]) => b.type === 'cryo_tank');
                            let resType = 'food';
                            outer: for (const [key] of cryoHexes) {
                                const [cq, cr] = key.split(',').map(Number);
                                for (const [nq, nr] of hexNeighbors(cq, cr)) {
                                    const nb = sC.buildings[`${nq},${nr}`];
                                    if (nb?.type === 'oxygen_plant') { resType = 'oxygen'; break outer; }
                                }
                            }
                            next = applyResourceDelta(sC, resType, ovC);
                        } else {
                            next = sC;
                        }
                        break;
                    }
                    case 'study': {
                        // 연구: Depot 직접 (로컬 저장소 미경유 — rulebook p.2)
                        next = applyResourceDelta(next, 'sanity', amt);
                        break;
                    }
                    case 'craft_automatron': {
                        // 오토마트론: 실험실 로컬 → 초과분 글로벌
                        const { newState, overflow } = addToStore(next, 'laboratory', amt);
                        next = overflow > 0
                            ? { ...newState, automatron: Math.max(0, (newState.automatron || 0) + overflow) }
                            : newState;
                        break;
                    }
                    case 'craft_battery': {
                        // 배터리: 작업장 로컬 → 초과분 글로벌
                        const { newState, overflow } = addToStore(next, 'workshop', amt);
                        next = overflow > 0
                            ? { ...newState, batteries: Math.max(0, (newState.batteries || 0) + overflow) }
                            : newState;
                        break;
                    }
                    default: {
                        const survivalRes = ['food', 'oxygen', 'sanity', 'radiation'];
                        if (survivalRes.includes(res)) {
                            next = applyResourceDelta(next, res, amt);
                        } else {
                            next = { ...next, [res]: Math.max(0, (next[res] ?? 0) + amt) };
                        }
                        break;
                    }
                }
            }
            return advanceSlot(next);
        }

        case 'END_ACTIONS': {
            // 미사용 주사위당 정신력 -1 (룰북: "if you pick a die and don't use it - lose one Sanity")
            const unusedSlots = (state.dieSlots || []).filter(s => !s.used).length;
            let next = { ...state };
            if (unusedSlots > 0) {
                next = { ...next, sanity: clamp(next.sanity - unusedSlots, 0, 10) };
                next = checkGameOver(next);
                if (next.gameOver) return next;
            }
            if (state.noAccident) return advanceTurn(next);
            return { ...next, phase: 'accident' };
        }

        case 'SET_ACCIDENT_DIE': {
            if (action.idx !== 1) return state;  // idx 0 is the leftover die (read-only)
            const ad = [...(state.accidentDice || [null, null])];
            ad[1] = action.value;
            return { ...state, accidentDice: ad };
        }

        case 'RESOLVE_ACCIDENT': {
            const sum = (state.accidentDice || []).reduce((s, v) => s + (v || 0), 0);
            const result = ACCIDENTS[sum];
            let next = applyEffects(state, result?.effects ?? []);
            next = { ...next, accidentResult: result };
            return advanceTurn(next);
        }

        case 'RESOLVE_CONSUMPTION': {
            const cons = state.consumption;
            if (!cons) return advanceTurnFinal(state);
            let next = state;
            if (cons.food > 0)      next = applyResourceDelta(next, 'food', -cons.food);
            if (cons.oxygen > 0)    next = applyResourceDelta(next, 'oxygen', -cons.oxygen);
            if (cons.sanity > 0)    next = applyResourceDelta(next, 'sanity', -cons.sanity);
            if (cons.radiation > 0) next = applyResourceDelta(next, 'radiation', cons.radiation);
            if (next.gameOver) return next;
            return advanceTurnFinal(next);
        }

        case 'CHOOSE_TECH': {
            if (!state.pendingTech) return state;
            const opt = TECH_OPTIONS.find(o => o.id === action.techId);
            let next = { ...state, techChoices: [...state.techChoices, action.techId || '__dismiss__'], pendingTech: false };
            if (opt?.type === 'power')  next = { ...next, power: (next.power || 0) + 3 };
            if (opt?.type === 'radMax') next = { ...next, radiationMax: next.radiationMax + 3 };
            return next;
        }

        case 'START_CONSTRUCTION': {
            const apRemaining = state.apPool - state.apUsed;
            if (apRemaining <= 0) return state;
            return { ...state, construction: { step: 'select_building', buildingType: null } };
        }

        case 'SELECT_BUILDING': {
            if (state.construction?.step !== 'select_building') return state;
            return { ...state, construction: { step: 'place', buildingType: action.buildingType } };
        }

        case 'CANCEL_CONSTRUCTION': {
            return { ...state, construction: null };
        }

        // 분리기/재활용기 첫 배치 (1단계 — 헥스 선택 후 스텝1 설치)
        case 'START_BUILDING_SETUP': {
            const { buildingType } = action;
            const def = BUILDINGS[buildingType];
            const apRemaining = state.apPool - state.apUsed;
            if (!def?.setupSteps || apRemaining < (def.stepCost || 1)) return state;
            return { ...state, construction: { step: 'place_setup', buildingType } };
        }

        case 'PLACE_BUILDING_SETUP': {
            const { buildingType, q, r } = action;
            if (state.construction?.step !== 'place_setup' || state.construction.buildingType !== buildingType) return state;
            const def = BUILDINGS[buildingType];
            const key = `${q},${r}`;
            if (state.buildings[key]) return state;
            const isOuter = Math.max(Math.abs(q), Math.abs(r), Math.abs(q + r)) === MAP_RADIUS;
            if (isOuter && !state.roverBuilt) return state;
            const terrain = TERRAIN_MAP[key] || TERRAIN.BLANK;
            if (def.terrain !== 'any' && terrain !== def.terrain) return state;
            if (buildingType === 'recycler') {
                const hasAdj = hexNeighbors(q, r).some(([nq, nr]) => {
                    const nb = state.buildings[`${nq},${nr}`];
                    return nb?.type === 'separator' && nb.active;
                });
                if (!hasAdj) return state;
            }
            const stepCost = def.stepCost || 1;
            return advanceSlot({
                ...state,
                construction: null,
                apUsed: state.apUsed + stepCost,
                buildings: { ...state.buildings, [key]: { type: buildingType, setupStep: 1, active: false, store: 0 } },
            });
        }

        case 'PLACE_BUILDING': {
            const { buildingType, q, r } = action;
            if (state.construction?.step !== 'place' || state.construction.buildingType !== buildingType) return state;
            const apRemaining = state.apPool - state.apUsed;
            const recyclerMats = Object.values(state.buildings).filter(b => b.type === 'recycler').reduce((s, b) => s + (b.store || 0), 0);
            const localPower   = Object.values(state.buildings).filter(b => b.type === 'nuclear_pod' || b.type === 'amplifier').reduce((s, b) => s + (b.store || 0), 0);
            const ctx = { buildings: state.buildings, roverBuilt: state.roverBuilt, apRemaining, materials: state.materials + recyclerMats, power: state.power + localPower };
            if (!canPlaceBuilding(ctx, buildingType, q, r)) return state;

            const def = BUILDINGS[buildingType];
            const cost = def.cost;

            // 건설 비용: 자재는 recycler 로컬 먼저, 전력은 nuclear_pod/amplifier 로컬 먼저
            let next = { ...state, construction: null, apUsed: state.apUsed + (cost.g || 0) };

            if ((cost.m || 0) > 0) {
                // 재활용기(처리된 자재) 먼저, 부족분은 글로벌 — 분리기(원자재)는 건설에 직접 사용 불가
                const { newState: s2, unmet: um } = drainFromBuildingType(next, 'recycler', cost.m);
                next = { ...s2, materials: Math.max(0, (s2.materials || 0) - um) };
            }
            if ((cost.p || 0) > 0) {
                const { newState: s3, unmet: up } = drainFromStores(next, 'power', cost.p);
                next = { ...s3, power: Math.max(0, (s3.power || 0) - up) };
            }

            next = { ...next, buildings: { ...next.buildings, [`${q},${r}`]: { type: buildingType, setupStep: 1, active: true, store: 0 } } };

            if (buildingType === 'rover') next = { ...next, roverBuilt: true };

            // 건설 즉시 효과: 로컬 저장소에 쌓이는 것들
            const instantLocal = { research_site: ['sanity', 1], nuclear_pod: ['power', 1], rover: ['sanity', 1] };
            if (instantLocal[buildingType]) {
                const [res, amt] = instantLocal[buildingType];
                const { newState: sL, overflow } = addToStore(next, buildingType, amt);
                next = overflow > 0 ? applyResourceDelta(sL, res, overflow) : sL;
            }

            // 건설 즉시 효과: 로컬 저장소 (transceiver → 로컬 sanity +3, food/oxygen_plant → 로컬 +1)
            if (buildingType === 'transceiver') { const { newState: sT, overflow } = addToStore(next, 'transceiver', 3); next = overflow > 0 ? applyResourceDelta(sT, 'sanity', overflow) : sT; }
            if (buildingType === 'food_plant') {
                const { newState: sF, overflow } = addToStore(next, 'food_plant', 1);
                next = overflow > 0 ? applyResourceDelta(sF, 'food', overflow) : sF;
                // 인접 식량플랜트마다 Depot +2
                const adjFood = hexNeighbors(q, r).filter(([nq, nr]) => next.buildings[`${nq},${nr}`]?.type === 'food_plant').length;
                if (adjFood > 0) next = applyResourceDelta(next, 'food', adjFood * 2);
            }
            if (buildingType === 'oxygen_plant') { const { newState: sO, overflow } = addToStore(next, 'oxygen_plant', 1); next = overflow > 0 ? applyResourceDelta(sO, 'oxygen', overflow) : sO; }
            if (buildingType === 'cryo_tank') {
                const { newState: sC, overflow } = addToStore(next, 'cryo_tank', 2);
                if (overflow > 0) {
                    // 인접 플랜트 타입 판별로 오버플로우 흡수
                    const hasOxy = hexNeighbors(q, r).some(([nq, nr]) => next.buildings[`${nq},${nr}`]?.type === 'oxygen_plant');
                    next = applyResourceDelta(sC, hasOxy ? 'oxygen' : 'food', overflow);
                } else { next = sC; }
            }

            // Laboratory: 건설 시 오토마트론 +3 즉시 로컬
            if (buildingType === 'laboratory') {
                const { newState: sA, overflow } = addToStore(next, 'laboratory', 3);
                next = overflow > 0 ? { ...sA, automatron: Math.max(0, (sA.automatron || 0) + overflow) } : sA;
            }

            if (buildingType === 'nuclear_pod') {
                const adjAmp = hexNeighbors(q, r).some(([nq, nr]) => next.buildings[`${nq},${nr}`]?.type === 'amplifier');
                if (adjAmp) {
                    const { newState: sP, overflow } = addToStore(next, 'nuclear_pod', 1);
                    next = overflow > 0 ? { ...sP, power: Math.max(0, (sP.power || 0) + overflow) } : sP;
                }
            }
            if (buildingType === 'amplifier') {
                const podCount = hexNeighbors(q, r).filter(([nq, nr]) => next.buildings[`${nq},${nr}`]?.type === 'nuclear_pod').length;
                if (podCount > 0) {
                    const { newState: sP2, overflow } = addToStore(next, 'amplifier', podCount);
                    next = overflow > 0 ? { ...sP2, power: Math.max(0, (sP2.power || 0) + overflow) } : sP2;
                }
            }

            next = advanceSlot(next);
            return checkGameOver(next);
        }

        case 'TOGGLE_COMBINE': {
            if (state.phase !== 'action') return state;
            if ((state.dieSlots || []).some(s => s.used)) return state;
            const slots = state.dieSlots || [];
            const combined = !state.combineMode;
            if (combined) {
                return { ...state, combineMode: true, apPool: slots.reduce((s, sl) => s + sl.ap, 0), apUsed: 0 };
            } else {
                return { ...state, combineMode: false, apPool: slots[0]?.ap || 0, apUsed: 0 };
            }
        }

        case 'RESTART': return { ...INITIAL_STATE };

        default: return state;
    }
}

function advanceTurn(state) {
    // Consumption fires at end of turns 5, 10, 15, … (i.e. current turn % 5 === 0)
    if (state.turn % 5 === 0) {
        const cons = getConsumptionStage(state.turn);
        return { ...state, phase: 'consumption', consumption: cons };
    }
    return advanceTurnFinal(state);
}

function advanceTurnFinal(state) {
    let next = {
        ...state,
        turn: state.turn + 1,
        phase: 'input',
        dice: [null, null, null],
        actionIdx: [],
        apPool: 0,
        apUsed: 0,
        dieSlots: null,
        combineMode: false,
        accidentDice: [null, null],
        accidentResult: null,
        consumption: null,
        noAccident: false,
    };
    next = checkVictory(next);
    return next;
}

export default function useRecycledGame() {
    const [state, dispatch] = useReducer(reducer, INITIAL_STATE);

    return {
        state,
        setDie:             (idx, value)  => dispatch({ type: 'SET_DIE', idx, value }),
        confirmInput:       ()            => dispatch({ type: 'CONFIRM_INPUT' }),
        toggleDie:          (idx)         => dispatch({ type: 'TOGGLE_DIE', idx }),
        confirmSelect:      ()            => dispatch({ type: 'CONFIRM_SELECT' }),
        doAction:           (id, mult)    => dispatch({ type: 'DO_ACTION', id, mult: mult || 1 }),
        toggleCombine:      ()            => dispatch({ type: 'TOGGLE_COMBINE' }),
        endActions:         ()            => dispatch({ type: 'END_ACTIONS' }),
        setAccidentDie:     (idx, value)  => dispatch({ type: 'SET_ACCIDENT_DIE', idx, value }),
        resolveAccident:    ()            => dispatch({ type: 'RESOLVE_ACCIDENT' }),
        resolveConsumption: ()            => dispatch({ type: 'RESOLVE_CONSUMPTION' }),
        chooseTech:         (techId)        => dispatch({ type: 'CHOOSE_TECH', techId }),
        startConstruction:   ()              => dispatch({ type: 'START_CONSTRUCTION' }),
        selectBuilding:      (buildingType)  => dispatch({ type: 'SELECT_BUILDING', buildingType }),
        cancelConstruction:  ()              => dispatch({ type: 'CANCEL_CONSTRUCTION' }),
        placeBuilding:       (buildingType, q, r) => dispatch({ type: 'PLACE_BUILDING', buildingType, q, r }),
        startBuildingSetup:  (buildingType)  => dispatch({ type: 'START_BUILDING_SETUP', buildingType }),
        placeBuildingSetup:  (buildingType, q, r) => dispatch({ type: 'PLACE_BUILDING_SETUP', buildingType, q, r }),
        restart:             ()              => dispatch({ type: 'RESTART' }),
    };
}
